sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float segments;
uniform float angle;
half4 main(float2 coord) {
    float2 c = center * size;
    float2 d = coord - c;
    float slice = 6.2831853 / max(floor(segments), 1);
    float a = mod(atan(d.y, d.x) - radians(angle), slice);
    a = min(a, slice - a) + radians(angle);
    return image.eval(c + length(d) * float2(cos(a), sin(a)));
}
